// noise and a detuned saw climbing for two seconds, cut dead on the drop
const n = kit.noise('white'), bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.Q.value = 2;
kit.env(bp.frequency, [[0, 300], [1.98, 9000]], 'exp');
const gn = ctx.createGain(); kit.env(gn.gain, [[0, 0.01], [1.9, 0.8], [1.99, 0.001]], 'exp');
n.connect(bp).connect(gn).connect(ctx.destination); n.start(0);
for (const det of [-14, 14]) {
  const o = ctx.createOscillator(); o.type = 'sawtooth'; o.detune.value = det; kit.env(o.frequency, [[0, 110], [1.98, 880]], 'exp');
  const f = ctx.createBiquadFilter(); f.type = 'lowpass'; kit.env(f.frequency, [[0, 400], [1.98, 6000]], 'exp');
  const g = ctx.createGain(); kit.env(g.gain, [[0, 0.001], [1.9, 0.12], [1.99, 0.0001]], 'exp');
  o.connect(f).connect(g).connect(ctx.destination); o.start(0); o.stop(2);
}
